mapper.select:
SELECT COUNT( uae.id )AS loginNum , DATE_FORMAT(uae.log_in_time,'%Y-%m-%d') AS loginTime, ua.master_id as masterId FROM gc_user_access_ext uae LEFT JOIN gc_user_access AS ua ON uae.user_access_id = ua.id LEFT JOIN gc_user AS u ON u.id = ua.user_id WHERE ua.user_id in
#{userId}
AND DATE_FORMAT( uae.log_in_time, '%Y-%m-%d' ) >= #{startDate} AND DATE_FORMAT( uae.log_in_time, '%Y-%m-%d' ) <= #{endDate} GROUP BY DATE_FORMAT(uae.log_in_time,'%Y-%m-%d')

select id,manager_id as managerId,COUNT(id) as adminLoginNum,DATE_FORMAT(log_in_time,'%Y-%m-%d') AS loginTime from gc_user_access_ext
where manager_id = #{managerId}
  AND DATE_FORMAT( log_in_time, '%Y-%m-%d' ) >= #{startDate}
  AND DATE_FORMAT( log_in_time, '%Y-%m-%d' ) <= #{endDate}
GROUP BY DATE_FORMAT(log_in_time,'%Y-%m-%d')
